mapper.select:
SELECT 

WHERE e.account_id = #{accountId}
ORDER BY e.detected_at DESC
LIMIT #{limit}

SELECT 

WHERE e.in_use = TRUE
  AND e.entity_type = 'API_KEY'
  AND e.detected_at >= #{since}
ORDER BY e.detected_at DESC
LIMIT #{limit}

SELECT 

WHERE e.entity_type = 'GROUP'
  AND e.in_use = #{inUse}
  AND e.detected_at >= #{from}
  AND e.detected_at < #{to}
ORDER BY e.detected_at DESC
LIMIT #{limit}
